`,e.jsxs(l,{tab:"Schedules",plate:"zonnewijzer-1551",children:[e.jsxs(i,{title:"Warmup protects the unstable first steps",accent:2,number:"30",items:"4",children:[e.jsxs(t.ul,{children:[`
